  const contentText = `BT
/F1 16 Tf
50 780 Td
(${safeSchool}) Tj
0 -22 Td
/F1 12 Tf
(${safeApp}) Tj
0 -20 Td
/F1 10 Tf
(${safeMeta}) Tj
0 -30 Td
/F1 14 Tf
(${safeTitle}) Tj
0 -20 Td
/F1 10 Tf
(${safeDesc}) Tj
0 -30 Td
/F1 9 Tf
(Status: Dokumen Resmi Terverifikasi dan Tersimpan pada Database DAF Archive) Tj
ET`;

  const streamLength = Buffer.byteLength(contentText, 'utf8');

  const pdfString = `%PDF-1.4
1 0 obj
<< /Type /Catalog /Pages 2 0 R >>
endobj
2 0 obj
<< /Type /Pages /Kids [3 0 R] /Count 1 >>
endobj
3 0 obj
<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>
endobj
4 0 obj
<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>
endobj
5 0 obj
<< /Length ${streamLength} >>
stream
${contentText}
endstream
endobj
xref
0 6
0000000000 65535 f 
0000000009 00000 n 
0000000058 00000 n 
0000000115 00000 n 
0000000234 00000 n 
0000000311 00000 n 
trailer
<< /Size 6 /Root 1 0 R >>
startxref
${360 + streamLength}
%%EOF`;

  return Buffer.from(pdfString, 'utf8');
}

