const SNP_STRUCTURE = [
  { jabatan: 'kepsek', label: 'Kepala Sekolah', folders: ['Standar Pengelolaan (P)'] },
  { jabatan: 'waka_kurikulum', label: 'Waka Kurikulum', folders: ['Standar Isi (SI)', 'Standar Proses (SP)'] },
